import { useState } from "react";
export default function Form11() {
  const [form, setForm] = useState({
    name: "",
    email: "",
    age: "",
    genralinfo: "",
  });
  return (
    <>
      <form className="form" onSubmit={(e)=>{
        e.preventDefault()
      }}>
        <div className="div1">
          <div className="field">
            <label>Name</label>
            <input
              type="text"
              value={form.name}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
            />
          </div>

          <div className="field">
            <label>Email</label>
            <input
              type="email"
              value={form.email}
              onChange={(e) => setForm({ ...form, email: e.target.value })}
            />
          </div>

          <div className="field">
            <label>Age</label>
            <input
              type="number"
              value={form.age}
              onChange={(e) => setForm({ ...form, age: e.target.value })}
            />
          </div>
        </div>

        <div className="field">
          <label>Message</label>
          <textarea rows="4"></textarea>
        </div>

        <button className="btn">Submit</button>
      </form>
    </>
  );
}
